diff --git a/verify/identity.go b/verify/identity.go
index c5f83d5..eeea969 100644
--- a/verify/identity.go
+++ b/verify/identity.go
@@ -42,6 +42,8 @@ type checkIdentity struct {
 	Lockfiles   []identityLock
 	Environment identityEnvironment
 	Host        identityHost
+	// reuseEnvironment hashes the environment pairs without the per-attempt variables.
+	reuseEnvironment string
 }

 func canonicalJSON(v any) []byte {
@@ -78,7 +80,7 @@ func identityHash(v any) string {
 	return hex.EncodeToString(h[:])
 }
 func bytesHash(b []byte) string { h := sha256.Sum256(b); return hex.EncodeToString(h[:]) }
-func stableEnvironment(s *sys.Session, tools Tools) (identityEnvironment, []string, string) {
+func environmentValues(s *sys.Session, tools Tools) map[string]string {
 	values := map[string]string{}
 	for _, e := range s.Env {
 		if k, v, ok := strings.Cut(e, "="); ok {
@@ -88,10 +90,31 @@ func stableEnvironment(s *sys.Session, tools Tools) (identityEnvironment, []stri
 	for k, v := range tools.env() {
 		values[k] = v
 	}
-	path := values["PATH"]
 	for _, k := range []string{"KOGEN_STEP_RUN", "KOGEN_ACCEPTANCE_RUN", "KOGEN_CHECK_REPORT", "KOGEN_ACCEPTANCE_REPORT"} {
 		delete(values, k)
 	}
+	return values
+}
+
+// reuseEnvironmentHash hashes the environment pairs after dropping every KL_ variable,
+// KOGEN_ATTEMPT_ID and KOGEN_GENERATION, which differ per attempt.
+func reuseEnvironmentHash(values map[string]string) string {
+	names := make([]string, 0, len(values))
+	for k := range values {
+		if !strings.HasPrefix(k, "KL_") && k != "KOGEN_ATTEMPT_ID" && k != "KOGEN_GENERATION" {
+			names = append(names, k)
+		}
+	}
+	sort.Strings(names)
+	pairs := make([][2]string, 0, len(names))
+	for _, k := range names {
+		pairs = append(pairs, [2]string{k, values[k]})
+	}
+	return identityHash(pairs)
+}
+func stableEnvironment(s *sys.Session, tools Tools) (identityEnvironment, []string, string) {
+	values := environmentValues(s, tools)
+	path := values["PATH"]
 	names := make([]string, 0, len(values))
 	for k := range values {
 		names = append(names, k)
@@ -196,7 +219,7 @@ func probeIdentityTool(name, path, dir string, env []string) identityTool {
 }
 func snapshotIdentity(s *sys.Session, tools Tools, tree, dir string) checkIdentity {
 	env, processEnv, path := stableEnvironment(s, tools)
-	id := checkIdentity{Tree: tree, Tools: []identityTool{}, Lockfiles: []identityLock{}, Environment: env, Host: identityHost{runtime.GOARCH, runtime.GOOS}}
+	id := checkIdentity{Tree: tree, Tools: []identityTool{}, Lockfiles: []identityLock{}, Environment: env, Host: identityHost{runtime.GOARCH, runtime.GOOS}, reuseEnvironment: reuseEnvironmentHash(environmentValues(s, tools))}
 	for _, name := range []string{"go", "node", "npm", "ruby", "bundle", "python3", "elixir", "erl", "mix", "git", "quint"} {
 		id.Tools = append(id.Tools, probeIdentityTool(name, path, dir, processEnv))
 	}
@@ -216,6 +239,7 @@ type identityLogger struct {
 func (l *identityLogger) Log(e map[string]any) {
 	if e["event"] == "command" {
 		e["identity_sha256"] = identityHash([]any{e["command"], l.identity.Tree, l.identity.Tools, l.identity.Lockfiles, l.identity.Environment, l.identity.Host})
+		e["reuse_sha256"] = identityHash([]any{e["command"], l.identity.Tree, l.identity.Tools, l.identity.Lockfiles, l.identity.reuseEnvironment, l.identity.Host})
 	}
 	l.inner.Log(e)
 }

